SELECT
    COUNT(*) recorded_days,AVG(mood_score) average_mood_score,COALESCE(SUM(is_favorite='1'),0) favorite_count FROM
    diary_record WHERE user_id=#{userId} AND status='1' AND record_date BETWEEN #{start} AND #{end}

SELECT
    mood_code,COUNT(*) count FROM diary_record WHERE user_id=#{userId} AND status='1' AND record_date BETWEEN #{start}
    AND #{end} AND mood_code IS NOT NULL GROUP BY mood_code ORDER BY count DESC
